import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Globe, LayoutDashboard, Briefcase, FileUser, 
  Terminal, Bell, LogOut, CheckCircle2, Zap, Search, Plus, 
  Pencil, Trash2, Eye, UploadCloud, FileText,
  MapPin, Filter, Bookmark, X, ChevronRight
} from 'lucide-react';

const CandidateDashboard = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // Modal State
  const [isApplyModalOpen, setIsApplyModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState(null);

  const handleLogout = () => navigate('/home'); 

  const openApplyModal = (job) => {
    setSelectedJob(job);
    setIsApplyModalOpen(true);
  };

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <LayoutDashboard size={18} /> },
    { id: 'jobs', label: 'Available Jobs', icon: <Briefcase size={18} /> },
  ];

  const profileItems = [
    { id: 'resume', label: 'Manage Resume', icon: <FileUser size={18} /> },
    { id: 'skills', label: 'My Skills', icon: <Terminal size={18} /> },
  ];

  return (
    <div className="min-h-screen flex font-sans text-slate-900 bg-white relative">
      
      {/* Sidebar */}
      <aside className="w-72 bg-slate-50 border-r border-slate-100 flex flex-col p-8 sticky top-0 h-screen z-20">
        <div className="flex items-center gap-3 mb-12">
          <div className="bg-purple-600 p-2 rounded-xl shadow-lg shadow-purple-500/10">
            <Globe size={24} className="text-white"/>
          </div>
          <span className="text-2xl font-black tracking-tighter text-slate-950">Talent<span className="text-purple-600">Pool</span></span>
        </div>

        <nav className="flex-1 space-y-1">
          <div className="pb-4 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Menu</div>
          {menuItems.map(item => (
            <SideBtn key={item.id} icon={item.icon} label={item.label} active={activeTab === item.id} onClick={() => setActiveTab(item.id)} />
          ))}
          <div className="pt-8 pb-4 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Profile</div>
          {profileItems.map(item => (
            <SideBtn key={item.id} icon={item.icon} label={item.label} active={activeTab === item.id} onClick={() => setActiveTab(item.id)} />
          ))}
        </nav>

        <div className="pt-8 border-t border-slate-100">
          <SideBtn icon={<LogOut size={18}/>} label="Logout" className="text-red-600 hover:bg-red-50" onClick={handleLogout} />
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 p-12 overflow-y-auto text-slate-900">
        {activeTab === 'dashboard' && <DashboardHome onSeeJobs={() => setActiveTab('jobs')} onApply={openApplyModal} />}
        {activeTab === 'jobs' && <AvailableJobsView onApply={openApplyModal} />}
        {activeTab === 'skills' && <SkillsView />}
        {activeTab === 'resume' && <ResumeView />}
      </main>

      {/* Apply Modal Component */}
      {isApplyModalOpen && (
        <ApplyModal 
          job={selectedJob} 
          onClose={() => setIsApplyModalOpen(false)} 
        />
      )}
    </div>
  );
};

// --- NEW APPLY MODAL COMPONENT ---
const ApplyModal = ({ job, onClose }) => {
  if (!job) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-300">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={onClose}></div>
      
      {/* Modal Content */}
      <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden animate-in zoom-in-95 duration-300">
        {/* Modal Header */}
        <div className="p-8 border-b border-slate-50 flex justify-between items-start">
          <div className="text-left">
            <h2 className="text-2xl font-black text-slate-950 mb-1">{job.title}</h2>
            <p className="text-slate-500 font-bold text-sm">{job.company} • {job.location || 'Remote'}</p>
            <div className="flex gap-2 mt-4">
               {job.tags?.map(t => (
                 <span key={t} className="text-[10px] font-black uppercase text-purple-700 bg-purple-50 px-3 py-1 rounded-lg border border-purple-100">{t}</span>
               ))}
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full text-slate-400 transition-colors">
            <X size={24} />
          </button>
        </div>

        {/* Modal Body */}
        <div className="p-8 space-y-8 max-h-[70vh] overflow-y-auto custom-scrollbar">
          {/* Section: Personal Info */}
          <section className="text-left">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Personal Information</h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-600 ml-1">Full Name</label>
                <input type="text" defaultValue="Alex Johnson" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:border-purple-200" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-600 ml-1">Email Address</label>
                <input type="email" defaultValue="alex.johnson@example.com" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:border-purple-200" />
              </div>
            </div>
          </section>

          {/* Section: Resume Preview */}
          <section className="text-left">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Resume</h3>
            <div className="flex items-center justify-between bg-slate-50 border border-slate-100 rounded-2xl p-4">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-white rounded-xl text-purple-600 border border-slate-100"><FileText size={20}/></div>
                <div>
                  <p className="text-sm font-black text-slate-900 leading-none">alex_johnson_resume_2024.pdf</p>
                  <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">Uploaded 2 days ago • 1.2 MB</p>
                </div>
              </div>
              <button className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-600 bg-white px-4 py-2 rounded-lg border border-slate-100 hover:bg-slate-50 transition-all">
                Change
              </button>
            </div>
          </section>

          {/* Section: Additional Information */}
          <section className="text-left space-y-4">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Additional Information</h3>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-600 ml-1">Cover Letter (Optional)</label>
              <textarea placeholder="Write a brief note explaining why you are a good fit..." className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:border-purple-200 h-24 resize-none" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-600 ml-1">Notice Period</label>
                <input type="text" placeholder="e.g. 30 Days" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:border-purple-200" />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-600 ml-1">Expected Salary</label>
                <input type="text" placeholder="e.g. $120,000 / year" className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:border-purple-200" />
              </div>
            </div>
          </section>
        </div>

        {/* Modal Footer */}
        <div className="p-8 bg-slate-50/50 border-t border-slate-50 flex gap-4">
          <button onClick={onClose} className="flex-1 bg-white border border-slate-200 py-4 rounded-2xl text-xs font-black uppercase tracking-widest text-slate-600 hover:bg-slate-100 transition-all">Cancel</button>
          <button className="flex-[2] bg-purple-600 hover:bg-purple-700 text-white py-4 rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl shadow-purple-600/20 transition-all flex items-center justify-center gap-2">
            Submit Application <ChevronRight size={16} />
          </button>
        </div>
      </div>
    </div>
  );
};

// --- MODIFIED VIEW COMPONENTS ---

const DashboardHome = ({ onSeeJobs, onApply }) => (
  <div className="animate-in fade-in duration-700">
    <header className="flex justify-between items-center mb-12">
      <div className="text-left">
        <h1 className="text-4xl font-black tracking-tight mb-2 text-slate-950">Welcome back, <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-600 to-blue-600">Sweatha!</span></h1>
        <p className="text-slate-600 font-medium">Here's what's happening with your job applications today.</p>
      </div>
      <HeaderIcons />
    </header>

    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-10">
      <StatCard label="Applications Sent" value="12" icon={<Zap size={20} />} color="text-blue-600" />
      <StatCard label="Profile Completion" value="85%" icon={<CheckCircle2 size={20} />} color="text-purple-600" />
      <StatCard label="Verified Skills" value="8" icon={<Terminal size={20} />} color="text-amber-600" />
    </div>

    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-6">
        <div className="flex justify-between items-center px-2">
           <h3 className="text-xl font-black tracking-tight uppercase text-slate-950">Recommended for you</h3>
           <button onClick={onSeeJobs} className="text-xs font-black text-purple-600 hover:text-purple-700 transition-colors uppercase tracking-widest">View All Jobs</button>
        </div>
        <JobCard 
          onApply={() => onApply({ title: "Senior React Developer", company: "TechCorp Inc.", location: "Remote", tags: ['React.js', 'Node.js', 'MongoDB'] })}
          title="Senior React Developer" company="TechCorp Inc." location="Remote • Full-time" tags={['React.js', 'Node.js', 'MongoDB']} 
        />
        <JobCard 
          onApply={() => onApply({ title: "Full Stack Engineer", company: "Startup Hub", location: "New York, NY", tags: ['JavaScript', 'Express.js', 'PostgreSQL'] })}
          title="Full Stack Engineer" company="Startup Hub" location="New York, NY • Hybrid" tags={['JavaScript', 'Express.js', 'PostgreSQL']} 
        />
      </div>
      <SkillsSidebar />
    </div>
  </div>
);

const AvailableJobsView = ({ onApply }) => (
  <div className="animate-in slide-in-from-bottom-4 duration-700">
    <header className="mb-10 text-left">
      <p className="text-xs font-black text-purple-600 uppercase tracking-widest mb-2">Employee / Available Jobs</p>
      <h1 className="text-5xl font-black tracking-tighter mb-4 text-slate-950">Find Your Next Role</h1>
      <p className="text-slate-600 text-lg font-medium">Discover opportunities that match your skills and career goals.</p>
    </header>

    <div className="flex gap-4 mb-12">
      <div className="flex-1 relative group text-left">
        <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-purple-600 transition-colors" size={22} />
        <input type="text" placeholder="Search job title, skill, company..." className="w-full bg-slate-50 border border-slate-100 rounded-3xl py-5 pl-14 pr-6 outline-none focus:border-purple-200 focus:bg-white transition-all shadow-inner" />
      </div>
      <FilterBtn icon={<MapPin size={20}/>} label="Location" />
      <FilterBtn icon={<Briefcase size={20}/>} label="Job Type" />
    </div>

    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
      <PremiumJobCard 
        onApply={() => onApply({ title: "Senior React Developer", company: "TechCorp Inc.", location: "Remote", tags: ['React.js', 'Node.js', 'MongoDB'] })}
        title="Senior React Developer" company="TechCorp Inc." match="98%" salary="$120k - $150k" tags={['React.js', 'Node.js', 'MongoDB']} 
      />
      <PremiumJobCard 
        onApply={() => onApply({ title: "Full Stack Engineer", company: "Startup Hub", location: "New York, NY", tags: ['JavaScript', 'Express.js', 'REST APIs'] })}
        title="Full Stack Engineer" company="Startup Hub" match="88%" salary="$100k - $130k" tags={['JavaScript', 'Express.js', 'REST APIs']} 
      />
      <PremiumJobCard 
        onApply={() => onApply({ title: "Node.js Backend", company: "CloudSystems", location: "Remote", tags: ['Node.js', 'AWS', 'Docker'] })}
        title="Node.js Backend" company="CloudSystems" match="82%" salary="$60/hr" tags={['Node.js', 'AWS', 'Docker']} 
      />
    </div>
  </div>
);

// --- REUSABLE UI COMPONENTS ---

const SideBtn = ({ icon, label, active, onClick, className = "" }) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-sm font-bold transition-all ${active ? 'bg-purple-600 text-white shadow-lg shadow-purple-600/10' : 'text-slate-600 hover:bg-slate-100 hover:text-slate-950'} ${className}`}>
    {icon} {label}
  </button>
);

const PremiumJobCard = ({ title, company, match, salary, tags, onApply }) => (
  <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100 hover:border-purple-200 hover:bg-white transition-all group relative overflow-hidden shadow-sm">
    <div className="flex justify-between items-start mb-6">
      <div className="p-4 bg-purple-100 rounded-2xl text-purple-600"><Briefcase size={24}/></div>
      <span className="bg-green-100 text-green-700 border border-green-200 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tighter">{match} Match</span>
    </div>
    <div className="text-left">
      <h3 className="text-xl font-black group-hover:text-purple-600 transition-colors text-slate-950">{title}</h3>
      <p className="text-slate-500 font-bold text-sm mb-4">{company}</p>
      <div className="flex items-center gap-4 mb-8 text-xs font-bold text-slate-600">
        <span>Remote</span> • <span className="text-slate-900">{salary}</span>
      </div>
    </div>
    <div className="flex gap-3">
      <button onClick={onApply} className="flex-1 bg-purple-600 hover:bg-purple-700 text-white py-4 rounded-2xl text-xs font-black uppercase transition-all shadow-xl shadow-purple-600/10">Apply Now</button>
      <button className="p-4 bg-white border border-slate-100 rounded-2xl transition-all text-slate-500 hover:text-purple-600"><Bookmark size={18}/></button>
    </div>
  </div>
);

const JobCard = ({ title, company, location, tags, onApply }) => (
  <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 hover:border-slate-200 transition-all group cursor-pointer flex justify-between items-center shadow-sm">
    <div className="text-left">
      <h4 className="text-xl font-black tracking-tight group-hover:text-purple-600 transition-colors text-slate-950">{title}</h4>
      <p className="text-sm font-medium text-slate-600 mb-4">{company} • {location}</p>
      <div className="flex gap-2">
        {tags.map(t => <span key={t} className="text-[10px] font-black uppercase text-purple-700 bg-purple-100/50 px-3 py-1 rounded-lg">{t}</span>)}
      </div>
    </div>
    <button onClick={onApply} className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all">Apply Now</button>
  </div>
);

// --- OTHER VIEWS (MINIMIZED FOR BREVITY) ---
const SkillsView = () => (
  <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
    <header className="mb-10 text-left">
      <p className="text-xs font-black text-purple-600 uppercase tracking-[0.2em] mb-2">Employee / Profile / My Skills</p>
      <h1 className="text-4xl font-black tracking-tight mb-2 text-slate-950">My Skills</h1>
      <p className="text-slate-600 font-medium text-left">Manage your professional skills and proficiencies.</p>
    </header>
    <div className="bg-slate-50 border border-slate-100 rounded-[2.5rem] p-10 mb-10 text-left">
      <h3 className="text-lg font-black mb-8 text-slate-950">Add New Skill</h3>
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
        <div>
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-3 ml-1">Skill Name</label>
          <input type="text" placeholder="e.g., React.js" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 outline-none" />
        </div>
        <div>
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-3 ml-1">Proficiency</label>
          <select className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 outline-none"><option>Expert</option><option>Advanced</option></select>
        </div>
        <div>
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-3 ml-1">Years</label>
          <input type="text" placeholder="e.g., 5" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 outline-none" />
        </div>
